import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

const session: ChatSession = {
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content: 'hello', timestamp: SENT_AT}],
};

function rejectingProvider(rejection: unknown): AIProvider {
  return {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw rejection;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

async function observe(rejection: unknown) {
  const seen: Error[] = [];
  const hooks: OrchestratorHooks = {
    onError: async (_session, error) => {
      seen.push(error);
    },
  };
  const orchestrator = createChatOrchestrator(rejectingProvider(rejection), promptBuilder, undefined, {hooks});
  let thrown: unknown = 'did not throw';
  try {
    await orchestrator.processMessage(session);
  } catch (error) {
    thrown = error;
  }
  return {
    onErrorCalls: seen.length,
    isError: seen[0] instanceof Error,
    cause: (seen[0] as Error | undefined)?.cause,
    thrown,
  };
}

describe('onError for a rejection that is not an Error', () => {
  it.each([
    ['a string', 'plain string failure'],
    ['a plain object', {code: 'E_LIB', detail: 'library shape'}],
    ['undefined', undefined],
  ])('calls onError once with an Error caused by %s, and rejects with the original', async (_label, rejection) => {
    expect(await observe(rejection)).toEqual({
      onErrorCalls: 1,
      isError: true,
      cause: rejection,
      thrown: rejection,
    });
  });
});
EOF
mkdir -p .lore; cat > .lore/dod.md <<'EOF'
# Definition of Done

> A rejection that is not an `Error` — a thrown string, a plain object, a value from a library that rejects with its own shape — bypasses `onError` entirely while still propagating to the caller.

**Strategy: `direct`** — `createChatOrchestrator(...).processMessage` is the real entry point; a provider that rejects with a non-Error value exercises the `instanceof Error` gate in the catch today.

## Done when these pass

- [ ] **calls onError once with an Error caused by a string / a plain object / undefined, and rejects with the original** — onError fires once with an `Error` whose `cause` is the raw value; the caller still receives the raw value.
  `src/orchestration/chatOrchestratorOnError.acceptance.test.ts`
- [ ] Existing `chatOrchestrator.test.ts` stays unedited and green (an `Error` reaches onError as the same instance).

## Facets

- [ ] Wrap non-Error rejections in an Error with `cause` before calling `onError`; rethrow the original.
- [ ] Replace the recorded-flaw line in `specs/hal-engine-config-hooks/spec.md` with the new guarantee, linking this test.
- [ ] CHANGELOG entry for existing consumers.

## Out of scope

- `beforeSession` escaping the `try`; usage accounting across tool rounds (HALEngine#93).
EOF
